fn insert(oline: &Vec<char>, l: usize, nl: &Vec<char>, p: usize, at_pos: usize) -> Vec<char> {
    // Validate preconditions stated in the problem.
    assert!(l <= oline.len(), "l exceeds length of oline");
    assert!(p <= nl.len(), "p exceeds length of nl");
    assert!(at_pos <= l, "at_pos must be in [0, l]");

    let total_len = l.checked_add(p).expect("length overflow");

    let mut res: Vec<char> = Vec::with_capacity(total_len);

    // 1) first A chars of oline
    res.extend_from_slice(&oline[..at_pos]);

    // 2) first P chars of nl
    res.extend_from_slice(&nl[..p]);

    // 3) remaining chars of oline from A to L
    res.extend_from_slice(&oline[at_pos..l]);

    debug_assert_eq!(res.len(), total_len);
    res
}